```

A useful dataset would contain categories such as:

- **File management**: create, rename, move, delete files
- **Web browsing**: search, fill forms, download files
- **Office tasks**: documents, spreadsheets, presentations
- **Communication**: email, chat, calendar
- **System control**: settings, apps, network
- **Coding tasks**: open IDE, edit files, run commands
- **Visual grounding**: screenshots + mouse coordinates
- **Error recovery**: handling popups, wrong clicks, missing files

For training a model like a GUI agent, you would usually store **screenshots at every step plus the action taken**, not just text instructions.

import numpy as np
import json
import re
from collections import Counter

from huggingface_hub import hf_hub_download


# =====================================================
# CONFIG
# =====================================================

MAX_VOCAB = 5000

BETA = 2.0
ALPHA = 3.0
GAMMA = 2.0


ACTION_WEIGHTS = {

    "click": 0.5,
    "type": 1.5,
    "keypress": 1.0,
    "scroll": 0.4,
    "open": 2.0,
    "close": 0.5,
    "save": 1.3,
    "submit": 1.5,
    "navigate": 1.8

}



# =====================================================
# DOWNLOAD ONLY FILE
# =====================================================

def download_agentnet():

    return hf_hub_download(

        repo_id="xlangai/AgentNet",

        filename="agentnet_ubuntu_5k.jsonl",

        repo_type="dataset"

    )



# =====================================================
# LOAD JSONL
# =====================================================

def load_jsonl(path):

    data=[]

    with open(
        path,
        "r",
        encoding="utf8"
    ) as f:

        for line in f:

            if line.strip():

                data.append(
                    json.loads(line)
                )

    return data




# =====================================================
# FLATTEN JSON
# =====================================================

def extract_strings(obj):

    result=[]


    if isinstance(obj, dict):

        for value in obj.values():

            result.extend(
                extract_strings(value)
            )


    elif isinstance(obj,list):

        for value in obj:

            result.extend(
                extract_strings(value)
            )


    elif isinstance(obj,str):

        result.append(obj)


    return result




# =====================================================
# CREATE ACTION CORPUS
# =====================================================

def make_corpus(dataset):

    corpus=[]


    for item in dataset:


        strings=extract_strings(item)


        tokens=[]


        for s in strings:


            s=s.lower()


            s=re.sub(
                r"[^a-z0-9_ ]",
                "",
                s
            )


            parts=s.split()


            for p in parts:


                if len(p)>1:

                    tokens.append(
                        p
                    )



        if len(tokens)>1:

            corpus.append(
                " ".join(tokens)
            )



    text=". ".join(corpus)


    if len(text)==0:

        raise ValueError(
            "Dataset produced empty corpus"
        )


    return text





# =====================================================
# INFLUENCE SPACE MARKOV
# =====================================================


class InfluenceSpaceMarkov:


    def __init__(

        self,

        beta=BETA,

        alpha=ALPHA,

        gamma=GAMMA

    ):

        self.beta=beta
        self.alpha=alpha
        self.gamma=gamma




    def fit(self,text):


        sentences=re.split(

            r'(?<=[.!?])\s+',

            text

        )


        sentences=[

            s.split()

            for s in sentences

            if s.strip()

        ]



        words=[

            w

            for s in sentences

            for w in s

        ]



        freq=Counter(words)



        self.vocab=[

            w

            for w,c in freq.most_common(
                MAX_VOCAB
            )

        ]



        self.word_to_idx={

            w:i

            for i,w in enumerate(
                self.vocab
            )

        }



        n=len(self.vocab)


        print(
            "Vocabulary:",
            n
        )



        if n==0:

            raise ValueError(
                "No vocabulary"
            )



        # ---------------------------------
        # MARKOV MATRIX
        # ---------------------------------


        counts=np.zeros(

            (n,n),

            dtype=np.float32

        )



        for sentence in sentences:


            for a,b in zip(

                sentence[:-1],

                sentence[1:]

            ):


                if (

                    a in self.word_to_idx

                    and

                    b in self.word_to_idx

                ):


                    i=self.word_to_idx[a]

                    j=self.word_to_idx[b]


                    counts[i,j]+=ACTION_WEIGHTS.get(

                        a,

                        1.0

                    )



        self.counts=counts



        # ---------------------------------
        # INFLUENCE FIELD
        # ---------------------------------


        L=np.log1p(
            counts
        )



        Y=np.exp(

            self.beta*L

            +

            np.sin(
                self.gamma*L
            )

        ).astype(
            np.float32
        )



        Y[counts==0]=0



        ymax=max(
            float(Y.max()),
            1
        )



        Yn=Y/ymax



        Z=np.exp(

            self.alpha*Yn

            +

            np.sin(
                self.gamma*Yn
            )

        ).astype(
            np.float32
        )



        Z[Y==0]=0



        row=Z.sum(

            axis=1,

            keepdims=True

        )



        self.P=np.divide(

            Z,

            row,

            out=np.zeros_like(Z),

            where=row!=0

        )




        # ---------------------------------
        # CO-OCCURRENCE SPACE
        # ---------------------------------


        cooc=np.zeros(

            (n,n),

            dtype=np.float32

        )



        for sentence in sentences:


            for i,w in enumerate(sentence):


                if w not in self.word_to_idx:

                    continue



                wi=self.word_to_idx[w]


                for j in range(

                    max(
                        0,
                        i-3
                    ),

                    min(
                        len(sentence),
                        i+4
                    )

                ):


                    if i==j:

                        continue



                    other=sentence[j]


                    if other in self.word_to_idx:


                        wj=self.word_to_idx[other]


                        cooc[wi,wj]+=1




        norm=np.linalg.norm(

            cooc,

            axis=1,

            keepdims=True

        )


        norm[norm==0]=1



        self.embedding=(

            cooc/norm

        ).astype(
            np.float32
        )



        self.cosine=(

            self.embedding

            @

            self.embedding.T

        ).astype(
            np.float32
        )



        return self





    # =================================================
    # GENERATION
    # =================================================


    def influence_generate(

        self,

        start,

        length=50

    ):


        if start not in self.word_to_idx:

            start=np.random.choice(
                self.vocab
            )



        result=[start]

        current=start



        for _ in range(length):


            i=self.word_to_idx[current]


            p=self.P[i]



            if p.sum()==0:

                break



            current=np.random.choice(

                self.vocab,

                p=p

            )


            result.append(
                current
            )



        return result





    def semantic_generate(

        self,

        start,

        length=50

    ):


        if start not in self.word_to_idx:

            start=np.random.choice(
                self.vocab
            )



        result=[start]

        current=start



        for _ in range(length):


            i=self.word_to_idx[current]


            sim=self.cosine[i].copy()


            sim[i]=0


            sim=np.maximum(
                sim,
                0
            )


            if sim.sum()==0:

                break



            sim/=sim.sum()



            current=np.random.choice(

                self.vocab,

                p=sim

            )


            result.append(
                current
            )


        return result





    def intersection_generate(

        self,

        start,

        candidates=30,

        length=60

    ):


        semantic=self.semantic_generate(

            start,

            length

        )


        vectors=[

            self.embedding[
                self.word_to_idx[w]
            ]

            for w in semantic

        ]



        target=np.mean(

            vectors,

            axis=0

        )



        best=None



        for _ in range(candidates):


            path=self.influence_generate(

                start,

                length

            )


            vec=np.mean(

                [

                self.embedding[
                    self.word_to_idx[w]
                ]

                for w in path

                ],

                axis=0

            )



            score=float(

                np.dot(
                    vec,
                    target
                )

            )



            if best is None or score>best[0]:

                best=(

                    score,

                    path

                )


        return best






# =====================================================
# PROMPT SEED
# =====================================================

def prompt_endofunction(prompt):

    words=prompt.lower().split()


    if not words:

        return ""


    return words[

        int(

            abs(
                np.sin(
                    len(prompt)
                )
            )

            *

            (len(words)-1)

        )

    ]





# =====================================================
# RUN
# =====================================================


print(
    "Downloading AgentNet Ubuntu 5k..."
)


file=download_agentnet()


dataset=load_jsonl(
    file
)



print(
    "Samples:",
    len(dataset)
)



corpus=make_corpus(
    dataset
)



print(
    "Corpus characters:",
    len(corpus)
)



model=InfluenceSpaceMarkov()



model.fit(
    corpus
)



print(
    "READY"
)




while True:


    prompt=input(
        "\nTASK: "
    ).strip()



    if prompt.lower() in [
        "exit",
        "quit"
    ]:

        break



    seed=prompt_endofunction(
        prompt
    )



    score,path=model.intersection_generate(

        seed,

        candidates=30,

        length=60

    )



    print()

    print(
        " -> ".join(path)
    )

    print()

    print(
        "score:",
        score
    )

