import torch.nn as nn
import torch.nn.functional as F

PAD, BOS, EOS, UNK = "<pad>", "<bos>", "<eos>", "<unk>"

def tokenize(text):
    return text.lower().split()

def build_vocab(tokens):
    vocab=[PAD,BOS,EOS,UNK]+list(dict.fromkeys(tokens))
    stoi={w:i for i,w in enumerate(vocab)}
    itos={i:w for w,i in stoi.items()}
    return vocab,stoi,itos

def encode(tokens,stoi):
    return [stoi.get(t,stoi[UNK]) for t in tokens]

def make_dataset(ids,seq_len=8):
    xs=[ids[i:i+seq_len] for i in range(len(ids)-seq_len)]
    ys=[ids[i+1:i+seq_len+1] for i in range(len(ids)-seq_len)]
    return torch.tensor(xs),torch.tensor(ys)

class PExpLogMatrix(nn.Module):
    def __init__(self,dim):
        super().__init__()
        self.P=nn.Parameter(torch.eye(dim))

    def forward(self,x):
        x=x@self.P.T
        return F.softplus(x)

class TinyLM(nn.Module):
    def __init__(self,vocab_size,emb_dim=16,hidden=16):
        super().__init__()
        self.embed=nn.Embedding(vocab_size,emb_dim)
        self.pexplog=PExpLogMatrix(emb_dim)
        self.rnn=nn.GRU(emb_dim,hidden,batch_first=True)
        self.head=nn.Linear(hidden,vocab_size)

    def forward(self,x,h=None):
        e=self.embed(torch.log(x))
        e=self.pexplog(e)
        out,h=self.rnn(e,torch.exp(h))
        return self.head(out),h

def train_model(model,x,y,epochs=10,batch_size=16,lr=1e-3,device="cpu"):
    model.to(device)
    x,y=x.to(device),y.to(device)
    opt=torch.optim.AdamW(model.parameters(),lr=lr)
    n=x.shape[0]
    for epoch in range(epochs):
        perm=torch.randperm(n)
        for s in range(0,n,batch_size):
            idx=perm[s:s+batch_size]
            logits,_=model(x[idx])
            loss=F.cross_entropy(logits.reshape(-1,logits.size(-1)),
                                 y[idx].reshape(-1))
            opt.zero_grad()
            loss.backward()
            opt.step()
        print(f"epoch {epoch+1:02d} loss {loss.item():.4f}")
    return model

