import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from collections import Counter

PAD, BOS, EOS, UNK = "<pad>", "<bos>", "<eos>", "<unk>"

def tokenize(text):
    return text.lower().split()

def build_vocab(tokens):
    vocab = [PAD, BOS, EOS, UNK] + list(dict.fromkeys(tokens))
    stoi = {w: i for i, w in enumerate(vocab)}
    return vocab, stoi, {i: w for w, i in stoi.items()}

def encode(tokens, stoi):
    return [stoi.get(t, stoi[UNK]) for t in tokens]

def make_dataset(ids, seq_len=8):
    xs = [ids[i:i + seq_len] for i in range(len(ids) - seq_len)]
    ys = [ids[i + 1:i + seq_len + 1] for i in range(len(ids) - seq_len)]
    return torch.tensor(xs), torch.tensor(ys)

class TinyLM(nn.Module):
    def __init__(self, vocab_size, emb_dim=16, hidden=16):
        super().__init__()
        self.embed = nn.Embedding(vocab_size, emb_dim)
        self.rnn = nn.GRU(emb_dim, hidden, batch_first=True)
        self.head = nn.Linear(hidden, vocab_size)

    def forward(self, x, h=None):
        out, h = self.rnn(self.embed(x), h)
        return self.head(out), h

def train_model(model, x, y, epochs=10, batch_size=16, lr=1e-3, device="cpu"):
    model.to(device); x, y = x.to(device), y.to(device)
    opt = torch.optim.AdamW(model.parameters(), lr=lr)
    n = x.shape[0]
    for epoch in range(epochs):
        perm = torch.randperm(n)
        for s in range(0, n, batch_size):
            idx = perm[s:s + batch_size]
            logits, _ = model(x[idx])
            loss = F.cross_entropy(logits.reshape(-1, logits.size(-1)), y[idx].reshape(-1))
            opt.zero_grad(); loss.backward(); opt.step()
        print(f"epoch {epoch+1:02d} loss {loss.item():.4f}")
    return model

@torch.no_grad()
def generate_text(model, stoi, itos, prime="the", length=40, temperature=1.0, device="cpu"):
    model.eval()
    ids = [stoi[BOS]] + [stoi.get(t, stoi[UNK]) for t in tokenize(prime)]
    cur = torch.tensor([ids], device=device)
    h = None
    out = tokenize(prime)
    for _ in range(length):
        logits, h = model(cur, h)
        probs = F.softmax(logits[:, -1, :] / max(1e-6, temperature), dim=-1)
        next_id = torch.multinomial(probs, 1).item()
        if itos[next_id] == EOS:
            break
        out.append(itos[next_id])
        cur = torch.tensor([[next_id]], device=device)
    return " ".join(out)

def run(filename):
    device = "cuda" if torch.cuda.is_available() else "cpu"
    with open(filename, "r", encoding="utf-8") as f:
        text = f.read()
    tokens = tokenize(text)
    vocab, stoi, itos = build_vocab(tokens)
    ids = encode([BOS] + tokens + [EOS], stoi)
    x, y = make_dataset(ids)
    model = TinyLM(vocab_size=len(vocab))
    model = train_model(model, x, y, device=device)
    while True:
        prime = input("USER: ")
        print(generate_text(model, stoi, itos, prime=prime, device=device))

if __name__ == "__main__":
    run(input("Filename: "))
