class SparseSymbolManifest:
    """
    Sparse finite-context word model.

    Learned statistical orders:

        unigram:
            P(x)

        bigram:
            P(x | previous)

        trigram:
            P(x | previous_previous, previous)

    Generation uses a larger finite rolling context as a
    steering field while retaining sparse unigram/bigram/
    trigram statistics.

    Prompt steering:

        prompt unigrams
        prompt bigrams
        prompt trigrams
        prompt beam field

    Generation steering:

        finite-context summation
        probability peak detection
        wide smooth peak curves
        prompt gram attraction
        prompt beam attraction
        intrinsic beam attraction
        temperature sampling
    """

    START_TOKEN = "<START>"
    END_TOKEN = "<END>"

    MAX_LEARNED_ORDER = 3

    def __init__(
        self,
        max_symbols: int = 256,
        max_beams: int = 16,
        max_states: int = 32,
        context_window: int = 8,
        recency_power: float = 1.5,
    ):
        self.max_symbols = int(max_symbols)
        self.max_beams = max(1, int(max_beams))
        self.max_states = max(1, int(max_states))

        # ----------------------------------------------------
        # Finite context
        # ----------------------------------------------------

        self.context_window = max(
            1,
            int(context_window),
        )

        self.recency_power = max(
            0.0,
            float(recency_power),
        )

        # ----------------------------------------------------
        # Beam steering strengths
        # ----------------------------------------------------

        self.beam_strength = 0.75

        self.context_beam_strength = 1.25

        self.prompt_strength = 1.50

        self.prompt_bigram_strength = 1.50

        self.prompt_trigram_strength = 2.00

        # ----------------------------------------------------
        # Wide peak parameters
        # ----------------------------------------------------

        self.curve_width = 32.0

        self.peak_strength = 1.50

        self.peak_fraction = 0.20

        # ----------------------------------------------------
        # Symbol manifest
        # ----------------------------------------------------

        self.entries: Dict[
            SymbolIndex,
            SymbolManifestEntry,
        ] = {}

        # ----------------------------------------------------
        # Counts
        # ----------------------------------------------------

        self.symbol_counts: Dict[
            SymbolIndex,
            int,
        ] = defaultdict(int)

        self.total_symbols = 0

        self.sequences: List[
            List[SymbolIndex]
        ] = []

        # ----------------------------------------------------
        # Sparse graph
        # ----------------------------------------------------

        self.successors: Dict[
            SymbolIndex,
            Set[SymbolIndex],
        ] = defaultdict(set)

        # ----------------------------------------------------
        # Vocabulary
        # ----------------------------------------------------

        self.index_to_word: Dict[
            SymbolIndex,
            str,
        ] = {}

        self.word_to_index: Dict[
            str,
            SymbolIndex,
        ] = {}

        self.next_index = 0

        # ====================================================
        # UNIGRAM
        # ====================================================

        self.unigram_probs: Dict[
            SymbolIndex,
            float,
        ] = {}

        # ====================================================
        # BIGRAM
        # ====================================================

        self.transition_counts: Dict[
            SymbolIndex,
            Dict[SymbolIndex, int],
        ] = defaultdict(
            lambda: defaultdict(int)
        )

        self.transition_probs: Dict[
            SymbolIndex,
            Dict[SymbolIndex, float],
        ] = {}

        # ====================================================
        # TRIGRAM
        # ====================================================

        self.trigram_counts: Dict[
            Tuple[
                SymbolIndex,
                SymbolIndex,
            ],
            Dict[
                SymbolIndex,
                int,
            ],
        ] = defaultdict(
            lambda: defaultdict(int)
        )

        self.trigram_probs: Dict[
            Tuple[
                SymbolIndex,
                SymbolIndex,
            ],
            Dict[
                SymbolIndex,
                float,
            ],
        ] = {}

    # ========================================================
    # REGISTRATION
    # ========================================================

    def _ensure_entry(
        self,
        idx: SymbolIndex,
    ) -> None:

        if idx not in self.entries:
            self.entries[idx] = SymbolManifestEntry()

    def _register_word(
        self,
        word: str,
    ) -> SymbolIndex:

        if word not in self.word_to_index:

            if self.next_index >= self.max_symbols:

                raise ValueError(
                    f"Vocabulary exceeds "
                    f"max_symbols={self.max_symbols}"
                )

            idx = self.next_index

            self.next_index += 1

            self.word_to_index[word] = idx

            self.index_to_word[idx] = word

            self._ensure_entry(idx)

            return idx

        return self.word_to_index[word]

    # ========================================================
    # TOKENIZATION
    # ========================================================

    @staticmethod
    def tokenize(
        text: str,
    ) -> List[str]:
        """
        Whitespace tokenizer, matching the original model.
        """

        return text.split()

    # ========================================================
    # DATASET INGESTION
    # ========================================================

    def add_sequence_words(
        self,
        words: List[str],
    ) -> List[SymbolIndex]:

        words = [
            word
            for word in words
            if word.strip()
        ]

        if not words:
            return []

        padded_words = [
            self.START_TOKEN,
            self.START_TOKEN,
            *words,
            self.END_TOKEN,
        ]

        seq = [
            self._register_word(word)
            for word in padded_words
        ]

        self.sequences.append(seq)

        # ----------------------------------------------------
        # Symbol counts
        # ----------------------------------------------------

        for symbol in seq:

            self.symbol_counts[symbol] += 1

            self.total_symbols += 1

        # ----------------------------------------------------
        # Bigram counts
        # ----------------------------------------------------

        for current, nxt in zip(
            seq,
            seq[1:],
        ):

            self.transition_counts[
                current
            ][nxt] += 1

            self.successors[
                current
            ].add(nxt)

        # ----------------------------------------------------
        # Trigram counts
        # ----------------------------------------------------

        for i in range(
            len(seq) - 2
        ):

            previous_word = seq[i]

            current_word = seq[i + 1]

            next_word = seq[i + 2]

            self.trigram_counts[
                (
                    previous_word,
                    current_word,
                )
            ][next_word] += 1

        return seq

    def ingest_dataset_words(
        self,
        sequences: List[List[str]],
    ) -> None:

        for words in sequences:
            self.add_sequence_words(words)

        self._finalize_unigrams()
        self._finalize_transitions()
        self._finalize_trigrams()
        self._update_intrinsics()
        self._assign_beams_and_states()

    # ========================================================
    # PROBABILITY FINALIZATION
    # ========================================================

    def _finalize_unigrams(
        self,
    ) -> None:

        self.unigram_probs = {}

        if self.total_symbols <= 0:
            return

        for symbol, count in self.symbol_counts.items():

            self.unigram_probs[
                symbol
            ] = (
                count / self.total_symbols
            )

    def _finalize_transitions(
        self,
    ) -> None:

        self.transition_probs = {}

        for current, next_words in (
            self.transition_counts.items()
        ):

            total = sum(
                next_words.values()
            )

            if total:

                self.transition_probs[
                    current
                ] = {
                    nxt: count / total
                    for nxt, count
                    in next_words.items()
                }

    def _finalize_trigrams(
        self,
    ) -> None:

        self.trigram_probs = {}

        for context, next_words in (
            self.trigram_counts.items()
        ):

            total = sum(
                next_words.values()
            )

            if total:

                self.trigram_probs[
                    context
                ] = {
                    nxt: count / total
                    for nxt, count
                    in next_words.items()
                }

    # ========================================================
    # INTRINSICS
    # ========================================================

    def _update_intrinsics(
        self,
    ) -> None:

        if self.total_symbols == 0:
            return

        vocabulary_size = max(
            1,
            len(self.entries),
        )

        for symbol, entry in self.entries.items():

            entry.intrinsic.density = (
                self.symbol_counts[symbol]
                / self.total_symbols
            )

            out_degree = len(
                self.successors[symbol]
            )

            max_possible = max(
                1,
                vocabulary_size - 1,
            )

            entry.intrinsic.relation = (
                out_degree / max_possible
            )

            entry.intrinsic.volatility = (
                out_degree / max_possible
            )

            if symbol not in self.transition_probs:

                entry.intrinsic.coherence = 1.0

            else:

                probabilities = list(
                    self.transition_probs[
                        symbol
                    ].values()
                )

                if len(probabilities) <= 1:

                    entry.intrinsic.coherence = 1.0

                else:

                    entropy = -sum(
                        probability
                        * math.log(
                            probability + 1e-12
                        )
                        for probability
                        in probabilities
                    )

                    max_entropy = math.log(
                        len(probabilities)
                    )

                    entry.intrinsic.coherence = max(
                        0.0,
                        1.0
                        - entropy / max_entropy,
                    )

        # ----------------------------------------------------
        # Depth
        # ----------------------------------------------------

        depth_sums = defaultdict(float)

        depth_counts = defaultdict(int)

        for sequence in self.sequences:

            for position, symbol in enumerate(
                sequence
            ):

                depth_sums[symbol] += position

                depth_counts[symbol] += 1

        max_length = max(
            (
                len(sequence)
                for sequence
                in self.sequences
            ),
            default=1,
        )

        for symbol, entry in self.entries.items():

            if depth_counts[symbol]:

                average_position = (
                    depth_sums[symbol]
                    / depth_counts[symbol]
                )

                entry.intrinsic.depth = (
                    average_position
                    / max_length
                )

    # ========================================================
    # BEAM / STATE ASSIGNMENT
    # ========================================================

    def _assign_beams_and_states(
        self,
    ) -> None:

        beam_denominator = max(
            1,
            self.max_beams - 1,
        )

        state_denominator = max(
            1,
            self.max_states - 1,
        )

        for entry in self.entries.values():

            relation = (
                entry.intrinsic.relation
            )

            coherence = (
                entry.intrinsic.coherence
            )

            beam_score = min(
                1.0,
                (
                    relation
                    + coherence
                ) / 2.0,
            )

            beam_id = int(
                beam_score
                * beam_denominator
            )

            entry.beam.beam_id = max(
                0,
                min(
                    self.max_beams - 1,
                    beam_id,
                ),
            )

            entry.beam.affinity = beam_score

            volatility = (
                entry.intrinsic.volatility
            )

            depth = (
                entry.intrinsic.depth
            )

            state_score = min(
                1.0,
                (
                    volatility
                    + depth
                ) / 2.0,
            )

            state_id = int(
                state_score
                * state_denominator
            )

            entry.markov.state_id = max(
                0,
                min(
                    self.max_states - 1,
                    state_id,
                ),
            )

            entry.weight = (
                0.5
                * entry.intrinsic.density
                +
                0.5
                * entry.intrinsic.coherence
            )

    # ========================================================
    # CONFIGURATION
    # ========================================================

    def configure_generation(
        self,
        context_window: Optional[int] = None,
        recency_power: Optional[float] = None,
        beam_strength: Optional[float] = None,
        context_beam_strength: Optional[float] = None,
        prompt_strength: Optional[float] = None,
        prompt_bigram_strength: Optional[float] = None,
        prompt_trigram_strength: Optional[float] = None,
        curve_width: Optional[float] = None,
        peak_strength: Optional[float] = None,
        peak_fraction: Optional[float] = None,
    ) -> None:

        if context_window is not None:

            self.context_window = max(
                1,
                int(context_window),
            )

        if recency_power is not None:

            self.recency_power = max(
                0.0,
                float(recency_power),
            )

        if beam_strength is not None:

            self.beam_strength = max(
                0.0,
                float(beam_strength),
            )

        if context_beam_strength is not None:

            self.context_beam_strength = max(
                0.0,
                float(context_beam_strength),
            )

        if prompt_strength is not None:

            self.prompt_strength = max(
                0.0,
                float(prompt_strength),
            )

        if prompt_bigram_strength is not None:

            self.prompt_bigram_strength = max(
                0.0,
                float(prompt_bigram_strength),
            )

        if prompt_trigram_strength is not None:

            self.prompt_trigram_strength = max(
                0.0,
                float(prompt_trigram_strength),
            )

        if curve_width is not None:

            self.curve_width = max(
                1e-6,
                float(curve_width),
            )

        if peak_strength is not None:

            self.peak_strength = max(
                0.0,
                float(peak_strength),
            )

        if peak_fraction is not None:

            self.peak_fraction = max(
                0.0,
                min(
                    1.0,
                    float(peak_fraction),
                ),
            )

    # ========================================================
    # BEAM ACCESS
    # ========================================================

    def _get_beam_id(
        self,
        symbol: SymbolIndex,
    ) -> int:

        entry = self.entries.get(symbol)

        if entry is None:
            return 0

        return entry.beam.beam_id

    def _get_beam_affinity(
        self,
        symbol: SymbolIndex,
    ) -> float:

        entry = self.entries.get(symbol)

        if entry is None:
            return 0.0

        return entry.beam.affinity

    # ========================================================
    # FINITE CONTEXT DISTRIBUTIONS
    # ========================================================

    def _context_distributions(
        self,
        context: List[SymbolIndex],
    ) -> List[
        Tuple[
            int,
            Dict[SymbolIndex, float],
        ]
    ]:

        if not context:
            return []

        context = context[
            -self.context_window:
        ]

        maximum_order = min(
            self.MAX_LEARNED_ORDER,
            len(context),
        )

        distributions = []

        for order in range(
            1,
            maximum_order + 1,
        ):

            if order == 1:

                probabilities = (
                    self.unigram_probs
                )

            elif order == 2:

                current = context[-1]

                probabilities = (
                    self.transition_probs.get(
                        current,
                        {},
                    )
                )

            else:

                key = (
                    context[-2],
                    context[-1],
                )

                probabilities = (
                    self.trigram_probs.get(
                        key,
                        {},
                    )
                )

            if probabilities:

                distributions.append(
                    (
                        order,
                        probabilities,
                    )
                )

        return distributions

    # ========================================================
    # FINITE CONTEXT SUMMATION
    # ========================================================

    def summed_context_distribution(
        self,
        context: List[SymbolIndex],
    ) -> Dict[SymbolIndex, float]:

        distributions = (
            self._context_distributions(
                context
            )
        )

        if not distributions:
            return {}

        raw_weights = []

        for order, _ in distributions:

            weight = (
                float(order)
                ** self.recency_power
            )

            raw_weights.append(weight)

        total_weight = sum(
            raw_weights
        )

        if total_weight <= 0.0:
            return {}

        alphas = [
            weight / total_weight
            for weight in raw_weights
        ]

        summed = defaultdict(float)

        for (
            (
                order,
                probabilities,
            ),
            alpha,
        ) in zip(
            distributions,
            alphas,
        ):

            for symbol, probability in (
                probabilities.items()
            ):

                summed[symbol] += (
                    alpha
                    * probability
                )

        total = sum(
            summed.values()
        )

        if total <= 0.0:
            return {}

        return {
            symbol:
                probability / total
            for symbol, probability
            in summed.items()
        }

    # ========================================================
    # CONTEXT BEAM FIELD
    # ========================================================

    def _context_beam_field(
        self,
        context: List[SymbolIndex],
    ) -> Dict[int, float]:

        context = context[
            -self.context_window:
        ]

        if not context:
            return {}

        raw_weights = []

        for position in range(
            len(context)
        ):

            recency = position + 1

            raw_weights.append(
                recency
                ** self.recency_power
            )

        total = sum(
            raw_weights
        )

        if total <= 0.0:
            return {}

        field = defaultdict(float)

        for symbol, weight in zip(
            context,
            raw_weights,
        ):

            beam = self._get_beam_id(
                symbol
            )

            field[beam] += (
                weight / total
            )

        return dict(field)

    # ========================================================
    # PROMPT TOKEN EXTRACTION
    # ========================================================

    def _prompt_tokens(
        self,
        prompt: str,
    ) -> List[SymbolIndex]:

        if not prompt:
            return []

        words = self.tokenize(prompt)

        return [
            self.word_to_index[word]
            for word in words
            if word in self.word_to_index
            and word not in {
                self.START_TOKEN,
                self.END_TOKEN,
            }
        ]

    # ========================================================
    # PROMPT GRAM TOKEN RAISING
    # ========================================================

    def _prompt_gram_boosts(
        self,
        prompt: str,
    ) -> Dict[SymbolIndex, float]:
        """
        Raise every token appearing in the prompt.

        Contribution:

            unigram = 1.0

            bigram =
                prompt_bigram_strength

            trigram =
                prompt_trigram_strength

        Importantly, every member of each gram receives the
        boost, not only the predicted final token.
        """

        tokens = self._prompt_tokens(
            prompt
        )

        if not tokens:
            return {}

        boosts = defaultdict(float)

        # ----------------------------------------------------
        # UNIGRAM
        # ----------------------------------------------------

        for token in tokens:

            boosts[token] += 1.0

        # ----------------------------------------------------
        # BIGRAM
        # ----------------------------------------------------

        for i in range(
            len(tokens) - 1
        ):

            a = tokens[i]
            b = tokens[i + 1]

            boosts[a] += (
                self.prompt_bigram_strength
            )

            boosts[b] += (
                self.prompt_bigram_strength
            )

        # ----------------------------------------------------
        # TRIGRAM
        # ----------------------------------------------------

        for i in range(
            len(tokens) - 2
        ):

            a = tokens[i]
            b = tokens[i + 1]
            c = tokens[i + 2]

            boosts[a] += (
                self.prompt_trigram_strength
            )

            boosts[b] += (
                self.prompt_trigram_strength
            )

            boosts[c] += (
                self.prompt_trigram_strength
            )

        # ----------------------------------------------------
        # Normalize
        # ----------------------------------------------------

        maximum = max(
            boosts.values(),
            default=1.0,
        )

        if maximum <= 0.0:
            return {}

        return {
            token:
                value / maximum
            for token, value
            in boosts.items()
        }

    # ========================================================
    # PROMPT BEAM FIELD
    # ========================================================

    def _prompt_gram_beam_field(
        self,
        prompt: str,
    ) -> Dict[int, float]:

        boosts = (
            self._prompt_gram_boosts(
                prompt
            )
        )

        if not boosts:
            return {}

        field = defaultdict(float)

        for token, strength in (
            boosts.items()
        ):

            beam_id = (
                self._get_beam_id(
                    token
                )
            )

            field[beam_id] += strength

        total = sum(
            field.values()
        )

        if total <= 0.0:
            return {}

        return {
            beam:
                strength / total
            for beam, strength
            in field.items()
        }

    # ========================================================
    # BEAM SIMILARITY
    # ========================================================

    def _beam_similarity(
        self,
        candidate: SymbolIndex,
        beam_field: Dict[int, float],
    ) -> float:

        if not beam_field:
            return 0.0

        candidate_beam = (
            self._get_beam_id(
                candidate
            )
        )

        candidate_affinity = (
            self._get_beam_affinity(
                candidate
            )
        )

        field_strength = (
            beam_field.get(
                candidate_beam,
                0.0,
            )
        )

        return min(
            1.0,
            0.5 * candidate_affinity
            + 0.5 * field_strength,
        )

    # ========================================================
    # PEAK DETECTION
    # ========================================================

    def detect_peaks(
        self,
        probabilities: Dict[
            SymbolIndex,
            float,
        ],
    ) -> List[
        Tuple[
            SymbolIndex,
            float,
        ]
    ]:
        """
        Detect significant sparse peaks.

        A candidate is retained as a peak if it is above
        peak_fraction * maximum probability.

        The peaks are then used as centers for wide curves.
        """

        if not probabilities:
            return []

        maximum = max(
            probabilities.values()
        )

        threshold = (
            maximum
            * self.peak_fraction
        )

        peaks = [
            (
                symbol,
                probability,
            )
            for symbol, probability
            in probabilities.items()
            if probability >= threshold
        ]

        peaks.sort(
            key=lambda item: item[1],
            reverse=True,
        )

        return peaks

    # ========================================================
    # WIDE PEAK CURVE
    # ========================================================

    def _candidate_distance(
        self,
        candidate: SymbolIndex,
        peak: SymbolIndex,
    ) -> float:

        return abs(
            float(candidate)
            - float(peak)
        )

    def _wide_peak_curve(
        self,
        probabilities: Dict[
            SymbolIndex,
            float,
        ],
    ) -> Dict[
        SymbolIndex,
        float,
    ]:
        """
        Expand probability peaks into smooth wide curves.

        Each peak creates:

            exp(
                -(distance^2)
                / (2 * width^2)
            )

        Multiple peaks sum together.

        The calculation remains sparse because only symbols
        already present in the candidate distribution are
        evaluated.
        """

        if not probabilities:
            return {}

        peaks = self.detect_peaks(
            probabilities
        )

        if not peaks:
            return {}

        width = max(
            1e-6,
            self.curve_width,
        )

        curve = defaultdict(float)

        for candidate in probabilities:

            for peak, peak_probability in (
                peaks
            ):

                distance = (
                    self._candidate_distance(
                        candidate,
                        peak,
                    )
                )

                gaussian = math.exp(
                    -0.5
                    * (
                        distance
                        / width
                    ) ** 2
                )

                curve[candidate] += (
                    peak_probability
                    * gaussian
                )

        maximum = max(
            curve.values(),
            default=1.0,
        )

        if maximum <= 0.0:
            return {}

        return {
            symbol:
                value / maximum
            for symbol, value
            in curve.items()
        }

    # ========================================================
    # PROMPT DIRECT + GRAM FIELD
    # ========================================================

    def prompt_field(
        self,
        prompt: str,
    ) -> Dict[SymbolIndex, float]:
        """
        Public inspection method for the complete prompt
        gram field.
        """

        return self._prompt_gram_boosts(
            prompt
        )

    # ========================================================
    # FULL STEERING FIELD
    # ========================================================

    def steer_distribution(
        self,
        probabilities: Dict[
            SymbolIndex,
            float,
        ],
        context: List[SymbolIndex],
        prompt: str = "",
    ) -> Dict[
        SymbolIndex,
        float,
    ]:
        """
        Apply:

            intrinsic beam
            +
            finite-context beam
            +
            all prompt gram tokens
            +
            prompt gram beam
            +
            wide probability peak curves
        """

        if not probabilities:
            return {}

        context_beam = (
            self._context_beam_field(
                context
            )
        )

        prompt_grams = (
            self._prompt_gram_boosts(
                prompt
            )
        )

        prompt_beam = (
            self._prompt_gram_beam_field(
                prompt
            )
        )

        peak_curve = (
            self._wide_peak_curve(
                probabilities
            )
        )

        adjusted = {}

        for symbol, probability in (
            probabilities.items()
        ):

            # ------------------------------------------------
            # Intrinsic beam
            # ------------------------------------------------

            intrinsic_beam = (
                self._get_beam_affinity(
                    symbol
                )
            )

            # ------------------------------------------------
            # Finite context beam
            # ------------------------------------------------

            context_alignment = (
                self._beam_similarity(
                    symbol,
                    context_beam,
                )
            )

            # ------------------------------------------------
            # ALL prompt gram tokens
            # ------------------------------------------------

            prompt_token = (
                prompt_grams.get(
                    symbol,
                    0.0,
                )
            )

            # ------------------------------------------------
            # Prompt beam
            # ------------------------------------------------

            beam_id = (
                self._get_beam_id(
                    symbol
                )
            )

            prompt_beam_alignment = (
                prompt_beam.get(
                    beam_id,
                    0.0,
                )
            )

            # ------------------------------------------------
            # Wide curve
            # ------------------------------------------------

            curve = (
                peak_curve.get(
                    symbol,
                    0.0,
                )
            )

            # ------------------------------------------------
            # Total field
            # ------------------------------------------------

            field = (

                self.beam_strength
                * intrinsic_beam

                +

                self.context_beam_strength
                * context_alignment

                +

                self.prompt_strength
                * prompt_token

                +

                self.prompt_strength
                * prompt_beam_alignment

                +

                self.peak_strength
                * curve
            )

            # Numerical protection.

            field = max(
                -20.0,
                min(
                    20.0,
                    field,
                ),
            )

            adjusted[symbol] = (
                probability
                * math.exp(field)
            )

        total = sum(
            adjusted.values()
        )

        if total <= 0.0:
            return {}

        return {
            symbol:
                value / total
            for symbol, value
            in adjusted.items()
        }

    # ========================================================
    # SAMPLING
    # ========================================================

    def sample_next(
        self,
        context: List[SymbolIndex],
        temperature: float = 1.0,
        prompt: str = "",
    ) -> Optional[SymbolIndex]:

        probabilities = (
            self.summed_context_distribution(
                context
            )
        )

        if not probabilities:
            return None

        probabilities = (
            self.steer_distribution(
                probabilities,
                context,
                prompt,
            )
        )

        if not probabilities:
            return None

        temperature = max(
            1e-6,
            float(temperature),
        )

        symbols = list(
            probabilities.keys()
        )

        adjusted = [
            probability
            ** (
                1.0
                / temperature
            )
            for probability
            in probabilities.values()
        ]

        total = sum(
            adjusted
        )

        if total <= 0.0:
            return None

        adjusted = [
            value / total
            for value in adjusted
        ]

        return random.choices(
            symbols,
            weights=adjusted,
            k=1,
        )[0]

    # ========================================================
    # BACKWARDS COMPATIBLE TRIGRAM SAMPLER
    # ========================================================

    def sample_next_trigram(
        self,
        previous_idx: SymbolIndex,
        current_idx: SymbolIndex,
        temperature: float = 1.0,
        prompt: str = "",
    ) -> Optional[SymbolIndex]:

        return self.sample_next(
            context=[
                previous_idx,
                current_idx,
            ],
            temperature=temperature,
            prompt=prompt,
        )

    # ========================================================
    # GENERATION
    # ========================================================

    def generate_sequence_indices(
        self,
        start: Optional[SymbolIndex] = None,
        max_len: int = 20,
        temperature: float = 1.0,
        prompt: str = "",
    ) -> List[SymbolIndex]:

        if max_len <= 0:
            return []

        start_idx = (
            self.word_to_index.get(
                self.START_TOKEN
            )
        )

        if start_idx is None:
            return []

        generated = []

        # ----------------------------------------------------
        # Initial context
        # ----------------------------------------------------

        context = [
            start_idx,
            start_idx,
        ]

        if start is not None:

            generated.append(
                start
            )

            context = [
                start_idx,
                start,
            ]

        context = context[
            -self.context_window:
        ]

        # ----------------------------------------------------
        # Generation loop
        # ----------------------------------------------------

        for _ in range(max_len):

            next_idx = self.sample_next(
                context=context,
                temperature=temperature,
                prompt=prompt,
            )

            if next_idx is None:
                break

            next_word = (
                self.index_to_word[
                    next_idx
                ]
            )

            if next_word == self.END_TOKEN:
                break

            if next_word != self.START_TOKEN:

                generated.append(
                    next_idx
                )

            # ------------------------------------------------
            # Roll finite context
            # ------------------------------------------------

            context.append(
                next_idx
            )

            context = context[
                -self.context_window:
            ]

        return generated

    def generate_sequence_words(
        self,
        start_word: Optional[str] = None,
        max_len: int = 20,
        temperature: float = 1.0,
        prompt: str = "",
    ) -> List[str]:

        if start_word is not None:

            if start_word not in self.word_to_index:

                raise ValueError(
                    f"Start word '{start_word}' "
                    "is not in the learned vocabulary."
                )

            start_idx = (
                self.word_to_index[
                    start_word
                ]
            )

        else:

            start_idx = None

        indices = (
            self.generate_sequence_indices(
                start=start_idx,
                max_len=max_len,
                temperature=temperature,
                prompt=prompt,
            )
        )

        return [
            self.index_to_word[index]
            for index in indices
            if self.index_to_word[index]
            not in {
                self.START_TOKEN,
                self.END_TOKEN,
            }
        ]

    # ========================================================
    # INSPECTION: PEAKS
    # ========================================================

    def peak_table(
        self,
        context: List[SymbolIndex],
    ) -> List[Dict]:

        probabilities = (
            self.summed_context_distribution(
                context
            )
        )

        peaks = self.detect_peaks(
            probabilities
        )

        rows = []

        for symbol, probability in peaks:

            rows.append({
                "index": symbol,
                "word": self.index_to_word.get(
                    symbol,
                    "<unknown>",
                ),
                "probability": probability,
                "beam": self._get_beam_id(
                    symbol
                ),
                "beam_affinity":
                    self._get_beam_affinity(
                        symbol
                    ),
            })

        return rows

    # ========================================================
    # INSPECTION: PROMPT GRAMS
    # ========================================================

    def prompt_gram_table(
        self,
        prompt: str,
    ) -> List[Dict]:

        boosts = (
            self._prompt_gram_boosts(
                prompt
            )
        )

        rows = []

        for symbol, strength in sorted(
            boosts.items(),
            key=lambda item: item[1],
            reverse=True,
        ):

            rows.append({
                "index": symbol,
                "word": self.index_to_word.get(
                    symbol,
                    "<unknown>",
                ),
                "prompt_strength": strength,
                "beam": self._get_beam_id(
                    symbol
                ),
            })

        return rows

    # ========================================================
    # INSPECTION: BEAMS
    # ========================================================

    def beam_table(
        self,
    ) -> List[Dict]:

        groups = defaultdict(list)

        for symbol, entry in (
            self.entries.items()
        ):

            groups[
                entry.beam.beam_id
            ].append(symbol)

        rows = []

        for beam_id in sorted(groups):

            members = groups[beam_id]

            rows.append({
                "beam_id": beam_id,
                "count": len(members),
                "symbols": [
                    self.index_to_word[
                        symbol
                    ]
                    for symbol in members
                ],
            })

        return rows

    # ========================================================
    # INSPECTION: MANIFEST
    # ========================================================

    def manifest_table(
        self,
    ) -> List[Dict]:

        rows = []

        for idx in sorted(
            self.entries
        ):

            entry = self.entries[idx]

            rows.append({
                "index": idx,

                "word":
                    self.index_to_word.get(
                        idx,
                        "<unknown>",
                    ),

                "density":
                    entry.intrinsic.density,

                "relation":
                    entry.intrinsic.relation,

                "coherence":
                    entry.intrinsic.coherence,

                "volatility":
                    entry.intrinsic.volatility,

                "depth":
                    entry.intrinsic.depth,

                "beam_id":
                    entry.beam.beam_id,

                "beam_affinity":
                    entry.beam.affinity,

                "state_id":
                    entry.markov.state_id,

                "weight":
                    entry.weight,

                "successors": [
                    self.index_to_word[index]
                    for index in sorted(
                        self.successors.get(
                            idx,
                            [],
                        )
                    )
                ],
            })

        return rows

    # ========================================================
    # INSPECTION: TRIGRAMS
    # ========================================================

    def trigram_table(
        self,
    ) -> List[Dict]:

        rows = []

        for context, next_words in sorted(
            self.trigram_counts.items()
        ):

            previous_idx, current_idx = (
                context
            )

            total = sum(
                next_words.values()
            )

            for next_idx, count in sorted(
                next_words.items()
            ):

                rows.append({
                    "word_1":
                        self.index_to_word[
                            previous_idx
                        ],

                    "word_2":
                        self.index_to_word[
                            current_idx
                        ],

                    "word_3":
                        self.index_to_word[
                            next_idx
                        ],

                    "count":
                        count,

                    "probability":
                        count / total,
                })

        return rows

    # ========================================================
    # VOCABULARY
    # ========================================================

    def vocabulary(
        self,
        include_special_tokens: bool = False,
    ) -> List[str]:

        words = list(
            self.word_to_index.keys()
        )

        if include_special_tokens:
            return words

        return [
            word
            for word in words
            if word not in {
                self.START_TOKEN,
                self.END_TOKEN,
            }
        ]


