@dataclass
class OpticalTrace:

    events: list[
        tuple[
            str,
            tuple[Any, ...],
            Any,
        ]
    ] = field(
        default_factory=list
    )

    def record(
        self,
        operation: str,
        inputs: tuple[Any, ...],
        result: Any,
    ) -> Any:

        self.events.append(
            (
                operation,
                inputs,
                result,
            )
        )

        return result

    def print(
        self,
        limit: Optional[int] = None,
    ) -> None:

        events = self.events

        if limit is not None:
            events = events[:limit]

        for index, (
            operation,
            inputs,
            result,
        ) in enumerate(
            events,
            1,
        ):

            print(
                f"[{index}] "
                f"{operation}{inputs} "
                f"-> {result}"
            )

        if (
            limit is not None
            and len(self.events) > limit
        ):

            print(
                f"... "
                f"{len(self.events) - limit} "
                f"more events"
            )


