One caveat: **this is still a simulator unless you provide an actual `OpticalBackend` driver**. The SHA-256 algorithm is being interpreted from the `.q` file, while its 32-bit Boolean/arithmetic primitives are routed through the reduced-valve abstraction.

Yes. The important change is to make the compiler actually capable of loading a `.q` source file containing a SHA-256 implementation, rather than hard-coding SHA-256 inside the compiler.

Below is a complete replacement. It adds:

- `.q` file execution
- byte input from `--input`, `--file`, `--hex`, or stdin
- 32-bit optical operations
- `ROTR`, `SHR`, `AND32`, `OR32`, `XOR32`, `ADD32`
- lists and indexing
- function definitions/calls
- `for range(...)`
- `while`
- `if`
- `return`
- `len()`
- SHA-256 implemented **inside `sha256.q`**
- optional optical trace
- self-test against Python's `hashlib`
- the compiler no longer needs SHA-256 hard-coded into the compiler itself

Save the first file as **`q_compiler.py`**.

```python
#!/usr/bin/env python3
"""
Q optical compiler/interpreter.

Runs restricted .q programs through the reduced-valve optical
hardware abstraction layer.

Example:

    python q_compiler.py --program sha256.q --input abc

or:

    python q_compiler.py --program sha256.q --file message.bin

The SHA-256 algorithm itself lives in sha256.q.
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import sys
from dataclasses import dataclass, field
from typing import Any, Iterable, Optional


MAX_LOOP_ITERATIONS = 1_000_000
MASK32 = 0xFFFFFFFF


# ---------------------------------------------------------------------------
# BASIC VALIDATION
# ---------------------------------------------------------------------------

def nonnegative_int(name: str, value: Any) -> int:
    if isinstance(value, bool):
        raise ValueError(f"{name} expects integer, got bool")

    if not isinstance(value, int):
        raise ValueError(f"{name} expects integer, got {value!r}")

    if value < 0:
        raise ValueError(
            f"{name} expects nonnegative integer, got {value!r}"
        )

    return value


def bit(value: Any) -> int:
    value = nonnegative_int("bit", value)

    if value not in (0, 1):
        raise ValueError(f"expected bit, got {value}")

    return value


def u32(value: int) -> int:
    return int(value) & MASK32


# ---------------------------------------------------------------------------
# BIT CONVERSION
# ---------------------------------------------------------------------------

def int_to_bits(
    value: int,
    width: Optional[int] = None,
) -> list[int]:

    value = nonnegative_int("value", value)

    if width is None:
        width = max(1, value.bit_length())

    if width < 1:
        raise ValueError("width must be positive")

    if value >= (1 << width):
        raise ValueError(
            f"{value} does not fit in {width} bits"
        )

    return [
        (value >> i) & 1
        for i in range(width)
    ]


def bits_to_int(bits: Iterable[int]) -> int:

    result = 0

    for i, value in enumerate(bits):
        result |= bit(int(value)) << i

    return result


# ---------------------------------------------------------------------------
# OPTICAL HARDWARE
# ---------------------------------------------------------------------------

class SimulatedOptics:
    """
    Deterministic simulator.

    This represents the optical backend without requiring physical hardware.
    """

    def and_bit(self, a: int, b: int) -> int:
        return bit(a) & bit(b)

    def sum_bits(self, values: Iterable[int]) -> int:
        return sum(
            bit(int(value))
            for value in values
        )

    def sample(self, value: int) -> int:
        return int(value)


class OpticalBackend:
    """
    Adapter between Q machine and real optical hardware.

    A real driver can implement:

        and_bit(a, b)
        sum_bits(values)
        sample(value)
    """

    def __init__(
        self,
        driver: Optional[Any] = None,
        valve_count: int = 2,
    ):

        self.driver = driver or SimulatedOptics()
        self.valve_count = valve_count

    def and_bit(self, a: int, b: int) -> int:

        result = self.driver.and_bit(
            bit(a),
            bit(b),
        )

        return bit(result)

    def sum_bits(
        self,
        values: Iterable[int],
    ) -> int:

        return int(
            self.driver.sum_bits(values)
        )

    def sample(self, value: int) -> int:

        return int(
            self.driver.sample(value)
        )


# ---------------------------------------------------------------------------
# TRACE
# ---------------------------------------------------------------------------

@dataclass
class OpticalTrace:

    events: list[
        tuple[str, tuple[Any, ...], Any]
    ] = field(default_factory=list)

    def record(
        self,
        operation: str,
        inputs: tuple[Any, ...],
        result: Any,
    ) -> Any:

        self.events.append(
            (
                operation,
                inputs,
                result,
            )
        )

        return result

    def print(
        self,
        limit: Optional[int] = None,
    ):

        events = self.events

        if limit is not None:
            events = events[:limit]

        for index, (
            operation,
            inputs,
            result,
        ) in enumerate(events, 1):

            print(
                f"[{index}] "
                f"{operation}{inputs} -> {result}"
            )

        if (
            limit is not None
            and len(self.events) > limit
        ):

            print(
                f"... "
                f"{len(self.events) - limit} "
                f"more events"
            )


# ---------------------------------------------------------------------------
# REDUCED VALVE MACHINE
# ---------------------------------------------------------------------------

class ReducedValveMachine:

    def __init__(
        self,
        backend: Optional[OpticalBackend] = None,
        width: int = 32,
        trace: Optional[OpticalTrace] = None,
    ):

        self.backend = (
            backend
            or OpticalBackend()
        )

        self.width = width

        self.trace = (
            trace
            or OpticalTrace()
        )

    # ---------------------------------------------------------------
    # SINGLE BIT OPERATIONS
    # ---------------------------------------------------------------

    def and_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        result = self.backend.and_bit(
            bit(a),
            bit(b),
        )

        return self.trace.record(
            "AND",
            (a, b),
            result,
        )

    def or_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        result = int(
            self.backend.sum_bits(
                [bit(a), bit(b)]
            ) > 0
        )

        return self.trace.record(
            "OR",
            (a, b),
            result,
        )

    def xor_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        result = (
            self.backend.sum_bits(
                [bit(a), bit(b)]
            )
            & 1
        )

        return self.trace.record(
            "XOR",
            (a, b),
            result,
        )

    def not_bit(
        self,
        a: int,
    ) -> int:

        result = 1 - bit(a)

        return self.trace.record(
            "NOT",
            (a,),
            result,
        )

    # ---------------------------------------------------------------
    # SERIAL BINARY
    # ---------------------------------------------------------------

    def serial_binary(
        self,
        a: int,
        b: int,
        operation: str,
        width: Optional[int] = None,
    ) -> int:

        a = u32(a)
        b = u32(b)

        width = width or self.width

        a_bits = int_to_bits(
            a,
            width,
        )

        b_bits = int_to_bits(
            b,
            width,
        )

        output = []

        for slot, (
            ai,
            bi,
        ) in enumerate(
            zip(a_bits, b_bits)
        ):

            if operation == "AND":

                value = self.backend.and_bit(
                    ai,
                    bi,
                )

            elif operation == "OR":

                value = int(
                    self.backend.sum_bits(
                        [ai, bi]
                    ) > 0
                )

            elif operation == "XOR":

                value = (
                    self.backend.sum_bits(
                        [ai, bi]
                    )
                    & 1
                )

            else:

                raise ValueError(
                    f"unknown operation {operation}"
                )

            output.append(value)

            self.trace.record(
                f"{operation}[t={slot}]",
                (ai, bi),
                value,
            )

        return bits_to_int(output)

    # ---------------------------------------------------------------
    # 32-BIT OPERATIONS
    # ---------------------------------------------------------------

    def add32(
        self,
        *values: int,
    ) -> int:

        result = 0

        for value in values:

            result = self._add_raw(
                result,
                u32(value),
            )

            result &= MASK32

        return self.trace.record(
            "ADD32",
            tuple(values),
            result,
        )

    def _add_raw(
        self,
        a: int,
        b: int,
    ) -> int:

        carry = 0
        result = 0

        for slot in range(32):

            ai = (a >> slot) & 1
            bi = (b >> slot) & 1

            total = self.backend.sum_bits(
                [
                    ai,
                    bi,
                    carry,
                ]
            )

            output_bit = total & 1

            carry = int(total >= 2)

            result |= (
                output_bit << slot
            )

            self.trace.record(
                f"ADD32[t={slot}]",
                (ai, bi, carry),
                output_bit,
            )

        return result & MASK32

    def and32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return MASK32

        result = u32(values[0])

        for value in values[1:]:

            result = (
                self.serial_binary(
                    result,
                    u32(value),
                    "AND",
                    32,
                )
                & MASK32
            )

        return self.trace.record(
            "AND32",
            tuple(values),
            result,
        )

    def or32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return 0

        result = u32(values[0])

        for value in values[1:]:

            result = (
                self.serial_binary(
                    result,
                    u32(value),
                    "OR",
                    32,
                )
                & MASK32
            )

        return self.trace.record(
            "OR32",
            tuple(values),
            result,
        )

    def xor32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return 0

        result = u32(values[0])

        for value in values[1:]:

            result = (
                self.serial_binary(
                    result,
                    u32(value),
                    "XOR",
                    32,
                )
                & MASK32
            )

        return self.trace.record(
            "XOR32",
            tuple(values),
            result,
        )

    def not32(
        self,
        value: int,
    ) -> int:

        result = (
            ~u32(value)
        ) & MASK32

        return self.trace.record(
            "NOT32",
            (value,),
            result,
        )

    # ---------------------------------------------------------------
    # SHIFTS
    # ---------------------------------------------------------------

    def shr(
        self,
        value: int,
        amount: int,
    ) -> int:

        value = u32(value)
        amount = int(amount)

        if amount >= 32:
            result = 0
        else:
            result = value >> amount

        return self.trace.record(
            "SHR",
            (value, amount),
            result,
        )

    def shl(
        self,
        value: int,
        amount: int,
    ) -> int:

        result = (
            u32(value)
            << int(amount)
        ) & MASK32

        return self.trace.record(
            "SHL",
            (value, amount),
            result,
        )

    def rotr(
        self,
        value: int,
        amount: int,
    ) -> int:

        value = u32(value)
        amount %= 32

        if amount == 0:

            result = value

        else:

            result = (
                (value >> amount)
                |
                (
                    value
                    << (32 - amount)
                )
            ) & MASK32

        return self.trace.record(
            "ROTR",
            (value, amount),
            result,
        )

    # ---------------------------------------------------------------
    # INTEGER OPERATIONS
    # ---------------------------------------------------------------

    def multiply(
        self,
        a: int,
        b: int,
    ) -> int:

        result = 0
        row = a
        shift = 0

        while b >> shift:

            if (b >> shift) & 1:

                result = self.add32(
                    result,
                    row,
                )

            row = (
                row << 1
            ) & MASK32

            shift += 1

        return result & MASK32

    def subtract(
        self,
        a: int,
        b: int,
    ) -> int:

        a = u32(a)
        b = u32(b)

        result = (
            a - b
        ) & MASK32

        return self.trace.record(
            "SUB32",
            (a, b),
            result,
        )

    def compare(
        self,
        a: int,
        b: int,
    ) -> int:

        if a == b:
            result = 0
        elif a > b:
            result = 1
        else:
            result = -1

        return self.trace.record(
            "CMP",
            (a, b),
            result,
        )

    def eq(self, a, b):
        return int(
            self.compare(a, b) == 0
        )

    def ne(self, a, b):
        return int(
            self.compare(a, b) != 0
        )

    def lt(self, a, b):
        return int(
            self.compare(a, b) < 0
        )

    def le(self, a, b):
        return int(
            self.compare(a, b) <= 0
        )

    def gt(self, a, b):
        return int(
            self.compare(a, b) > 0
        )

    def ge(self, a, b):
        return int(
            self.compare(a, b) >= 0
        )


# ---------------------------------------------------------------------------
# Q RUNTIME
# ---------------------------------------------------------------------------

class QRuntime:

    def __init__(
        self,
        machine: ReducedValveMachine,
        data: bytes,
    ):

        self.machine = machine
        self.data = bytes(data)

    def byte(
        self,
        index: int,
    ) -> int:

        if index < 0:
            return 0

        if index >= len(self.data):
            return 0

        return self.data[index]

    def length(self) -> int:
        return len(self.data)

    def padded(self) -> bytes:

        message = bytearray(
            self.data
        )

        bit_length = (
            len(message) * 8
        )

        message.append(0x80)

        while (
            len(message) % 64
            != 56
        ):

            message.append(0)

        message.extend(
            bit_length.to_bytes(
                8,
                "big",
            )
        )

        return bytes(message)

    def word(
        self,
        index: int,
    ) -> int:

        padded = self.padded()

        offset = index * 4

        if (
            offset + 4
            > len(padded)
        ):

            return 0

        return int.from_bytes(
            padded[offset:offset + 4],
            "big",
        )

    def word_count(self) -> int:

        return len(
            self.padded()
        ) // 4


# ---------------------------------------------------------------------------
# Q FUNCTION SUPPORT
# ---------------------------------------------------------------------------

@dataclass
class QFunction:

    node: ast.FunctionDef


class QReturn(Exception):

    def __init__(
        self,
        value: Any,
    ):

        self.value = value


class QBreak(Exception):
    pass


class QContinue(Exception):
    pass


# ---------------------------------------------------------------------------
# EXPRESSION EVALUATOR
# ---------------------------------------------------------------------------

class ExpressionEvaluator(
    ast.NodeVisitor
):

    def __init__(
        self,
        machine: ReducedValveMachine,
        variables: dict[str, Any],
        functions: dict[str, QFunction],
        runtime: QRuntime,
        executor: "StatementExecutor",
    ):

        self.machine = machine
        self.variables = variables
        self.functions = functions
        self.runtime = runtime
        self.executor = executor

    def visit_Constant(
        self,
        node: ast.Constant,
    ):

        if (
            isinstance(node.value, int)
            or isinstance(node.value, str)
        ):

            return node.value

        raise SyntaxError(
            "unsupported constant"
        )

    def visit_Name(
        self,
        node: ast.Name,
    ):

        if node.id not in self.variables:

            raise NameError(
                f"undefined Q variable: "
                f"{node.id}"
            )

        return self.variables[node.id]

    def visit_List(
        self,
        node: ast.List,
    ):

        return [
            self.visit(element)
            for element in node.elts
        ]

    def visit_Tuple(
        self,
        node: ast.Tuple,
    ):

        return tuple(
            self.visit(element)
            for element in node.elts
        )

    def visit_Subscript(
        self,
        node: ast.Subscript,
    ):

        value = self.visit(
            node.value
        )

        index = self.visit(
            node.slice
        )

        return value[index]

    def visit_Index(
        self,
        node,
    ):

        return self.visit(
            node.value
        )

    def visit_UnaryOp(
        self,
        node: ast.UnaryOp,
    ):

        value = self.visit(
            node.operand
        )

        if isinstance(
            node.op,
            ast.Invert,
        ):

            return self.machine.not32(
                value
            )

        if isinstance(
            node.op,
            ast.USub,
        ):

            return (
                -int(value)
            ) & MASK32

        if isinstance(
            node.op,
            ast.UAdd,
        ):

            return +int(value)

        if isinstance(
            node.op,
            ast.Not,
        ):

            return int(
                not value
            )

        raise SyntaxError(
            "unsupported unary operation"
        )

    def visit_BinOp(
        self,
        node: ast.BinOp,
    ):

        left = self.visit(
            node.left
        )

        right = self.visit(
            node.right
        )

        if isinstance(
            node.op,
            ast.BitAnd,
        ):

            return self.machine.and32(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.BitOr,
        ):

            return self.machine.or32(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.BitXor,
        ):

            return self.machine.xor32(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.Add,
        ):

            if isinstance(left, str) or isinstance(right, str):
                return left + right

            return self.machine.add32(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.Sub,
        ):

            return self.machine.subtract(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.LShift,
        ):

            return self.machine.shl(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.RShift,
        ):

            return self.machine.shr(
                left,
                right,
            )

        if isinstance(
            node.op,
            ast.Mod,
        ):

            return left % right

        if isinstance(
            node.op,
            ast.Mult,
        ):

            return left * right

        raise SyntaxError(
            "unsupported binary operator"
        )

    def visit_BoolOp(
        self,
        node: ast.BoolOp,
    ):

        values = [
            self.visit(value)
            for value in node.values
        ]

        if isinstance(
            node.op,
            ast.And,
        ):

            return int(
                all(values)
            )

        return int(
            any(values)
        )

    def visit_Compare(
        self,
        node: ast.Compare,
    ):

        left = self.visit(
            node.left
        )

        result = True

        for op, operand in zip(
            node.ops,
            node.comparators,
        ):

            right = self.visit(
                operand
            )

            if isinstance(
                op,
                ast.Eq,
            ):

                current = (
                    left == right
                )

            elif isinstance(
                op,
                ast.NotEq,
            ):

                current = (
                    left != right
                )

            elif isinstance(
                op,
                ast.Lt,
            ):

                current = (
                    left < right
                )

            elif isinstance(
                op,
                ast.LtE,
            ):

                current = (
                    left <= right
                )

            elif isinstance(
                op,
                ast.Gt,
            ):

                current = (
                    left > right
                )

            elif isinstance(
                op,
                ast.GtE,
            ):

                current = (
                    left >= right
                )

            else:

                raise SyntaxError(
                    "unsupported comparison"
                )

            result = (
                result
                and current
            )

            left = right

        return int(result)

    def visit_Call(
        self,
        node: ast.Call,
    ):

        if not isinstance(
            node.func,
            ast.Name,
        ):

            raise SyntaxError(
                "only simple Q calls"
            )

        name = node.func.id

        args = [
            self.visit(arg)
            for arg in node.args
        ]

        # Optical primitives.

        if name == "ADD32":
            return self.machine.add32(*args)

        if name == "AND32":
            return self.machine.and32(*args)

        if name == "OR32":
            return self.machine.or32(*args)

        if name == "XOR32":
            return self.machine.xor32(*args)

        if name == "NOT32":
            return self.machine.not32(args[0])

        if name == "ROTR":
            return self.machine.rotr(
                args[0],
                args[1],
            )

        if name == "SHR":
            return self.machine.shr(
                args[0],
                args[1],
            )

        if name == "SHL":
            return self.machine.shl(
                args[0],
                args[1],
            )

        # Runtime.

        if name == "BYTE":
            return self.runtime.byte(
                args[0]
            )

        if name == "INPUT_LENGTH":
            return self.runtime.length()

        if name == "INPUT_WORD":
            return self.runtime.word(
                args[0]
            )

        if name == "WORD_COUNT":
            return self.runtime.word_count()

        # Python-like helpers available to Q.

        if name == "len":
            return len(args[0])

        if name == "range":
            return range(*args)

        if name == "int":
            return int(args[0])

        if name == "U32":
            return u32(args[0])

        # User-defined Q function.

        if name in self.functions:

            return self.executor.call_function(
                self.functions[name],
                args,
            )

        raise NameError(
            f"unknown Q function: {name}"
        )

    def generic_visit(
        self,
        node,
    ):

        raise SyntaxError(
            f"unsupported Q expression: "
            f"{type(node).__name__}"
        )


# ---------------------------------------------------------------------------
# STATEMENT EXECUTOR
# ---------------------------------------------------------------------------

class StatementExecutor(
    ast.NodeVisitor
):

    def __init__(
        self,
        machine: ReducedValveMachine,
        variables: Optional[
            dict[str, Any]
        ] = None,
        runtime: Optional[QRuntime] = None,
        functions: Optional[
            dict[str, QFunction]
        ] = None,
    ):

        self.machine = machine

        self.variables = (
            variables
            if variables is not None
            else {}
        )

        self.runtime = runtime

        self.functions = (
            functions
            if functions is not None
            else {}
        )

    def evaluate(
        self,
        node,
    ):

        return ExpressionEvaluator(
            self.machine,
            self.variables,
            self.functions,
            self.runtime,
            self,
        ).visit(node)

    def visit_Module(
        self,
        node: ast.Module,
    ):

        for statement in node.body:

            self.visit(
                statement
            )

    def visit_FunctionDef(
        self,
        node: ast.FunctionDef,
    ):

        self.functions[node.name] = (
            QFunction(node)
        )

    def call_function(
        self,
        function: QFunction,
        args: list[Any],
    ):

        node = function.node

        if len(args) != len(
            node.args.args
        ):

            raise TypeError(
                f"{node.name} expects "
                f"{len(node.args.args)} arguments"
            )

        local = dict(
            self.variables
        )

        for argument, value in zip(
            node.args.args,
            args,
        ):

            local[
                argument.arg
            ] = value

        child = StatementExecutor(
            self.machine,
            local,
            self.runtime,
            self.functions,
        )

        try:

            for statement in node.body:

                child.visit(
                    statement
                )

        except QReturn as returned:

            return returned.value

        return None

    def visit_Return(
        self,
        node: ast.Return,
    ):

        value = (
            self.evaluate(node.value)
            if node.value is not None
            else None
        )

        raise QReturn(value)

    def visit_Assign(
        self,
        node: ast.Assign,
    ):

        value = self.evaluate(
            node.value
        )

        for target in node.targets:

            self.assign(
                target,
                value,
            )

    def assign(
        self,
        target,
        value,
    ):

        if isinstance(
            target,
            ast.Name,
        ):

            self.variables[
                target.id
            ] = value

            return

        if isinstance(
            target,
            ast.Subscript,
        ):

            container = self.evaluate(
                target.value
            )

            index = self.evaluate(
                target.slice
            )

            container[index] = value

            return

        raise SyntaxError(
            "unsupported assignment target"
        )

    def visit_AugAssign(
        self,
        node: ast.AugAssign,
    ):

        if not isinstance(
            node.target,
            ast.Name,
        ):

            raise SyntaxError(
                "augmented assignment "
                "requires variable"
            )

        name = node.target.id

        lhs = self.variables[name]
        rhs = self.evaluate(
            node.value
        )

        if isinstance(
            node.op,
            ast.Add,
        ):

            value = self.machine.add32(
                lhs,
                rhs,
            )

        elif isinstance(
            node.op,
            ast.Sub,
        ):

            value = self.machine.subtract(
                lhs,
                rhs,
            )

        elif isinstance(
            node.op,
            ast.BitXor,
        ):

            value = self.machine.xor32(
                lhs,
                rhs,
            )

        elif isinstance(
            node.op,
            ast.BitAnd,
        ):

            value = self.machine.and32(
                lhs,
                rhs,
            )

        elif isinstance(
            node.op,
            ast.BitOr,
        ):

            value = self.machine.or32(
                lhs,
                rhs,
            )

        else:

            raise SyntaxError(
                "unsupported augmented operator"
            )

        self.variables[name] = value

    def visit_Expr(
        self,
        node: ast.Expr,
    ):

        if isinstance(
            node.value,
            ast.Call,
        ):

            if (
                isinstance(
                    node.value.func,
                    ast.Name,
                )
                and node.value.func.id
                == "print"
            ):

                values = [
                    self.evaluate(arg)
                    for arg in node.value.args
                ]

                print(*values)

                return

            if (
                isinstance(
                    node.value.func,
                    ast.Name,
                )
                and node.value.func.id
                == "print_hex"
            ):

                value = self.evaluate(
                    node.value.args[0]
                )

                print(
                    f"{u32(value):08x}"
                )

                return

            if (
                isinstance(
                    node.value.func,
                    ast.Name,
                )
                and node.value.func.id
                == "print_digest"
            ):

                values = [
                    self.evaluate(arg)
                    for arg in node.value.args
                ]

                print(
                    "".join(
                        f"{u32(value):08x}"
                        for value in values
                    )
                )

                return

        self.evaluate(
            node.value
        )

    def visit_If(
        self,
        node: ast.If,
    ):

        if self.evaluate(
            node.test
        ):

            for statement in node.body:

                self.visit(statement)

        else:

            for statement in node.orelse:

                self.visit(statement)

    def visit_While(
        self,
        node: ast.While,
    ):

        count = 0

        while self.evaluate(
            node.test
        ):

            count += 1

            if count > MAX_LOOP_ITERATIONS:

                raise RuntimeError(
                    "Q loop limit exceeded"
                )

            try:

                for statement in node.body:

                    self.visit(statement)

            except QBreak:

                break

            except QContinue:

                continue

    def visit_For(
        self,
        node: ast.For,
    ):

        if not isinstance(
            node.target,
            ast.Name,
        ):

            raise SyntaxError(
                "Q for target must be a variable"
            )

        iterable = self.evaluate(
            node.iter
        )

        for value in iterable:

            self.variables[
                node.target.id
            ] = value

            try:

                for statement in node.body:

                    self.visit(statement)

            except QBreak:

                break

            except QContinue:

                continue

    def visit_Break(
        self,
        node: ast.Break,
    ):

        raise QBreak()

    def visit_Continue(
        self,
        node: ast.Continue,
    ):

        raise QContinue()

    def visit_Pass(
        self,
        node: ast.Pass,
    ):

        pass

    def generic_visit(
        self,
        node,
    ):

        raise SyntaxError(
            f"unsupported Q statement: "
            f"{type(node).__name__}"
        )


# ---------------------------------------------------------------------------
# Q PROGRAM VALIDATION
# ---------------------------------------------------------------------------

FORBIDDEN = (
    ast.Import,
    ast.ImportFrom,
    ast.ClassDef,
    ast.AsyncFunctionDef,
    ast.AsyncFor,
    ast.AsyncWith,
    ast.With,
    ast.Try,
    ast.Raise,
    ast.Delete,
    ast.Global,
    ast.Nonlocal,
    ast.Lambda,
    ast.Yield,
    ast.YieldFrom,
)


ALLOWED_CALLS = {
    "ADD32",
    "AND32",
    "OR32",
    "XOR32",
    "NOT32",
    "ROTR",
    "SHR",
    "SHL",
    "BYTE",
    "INPUT_LENGTH",
    "INPUT_WORD",
    "WORD_COUNT",
    "U32",
    "len",
    "range",
    "int",
    "print",
    "print_hex",
    "print_digest",
}


def validate_q(
    tree: ast.AST,
):

    for node in ast.walk(tree):

        if isinstance(
            node,
            FORBIDDEN,
        ):

            raise SyntaxError(
                f"forbidden Q construct: "
                f"{type(node).__name__}"
            )

        if isinstance(
            node,
            ast.Call,
        ):

            if not isinstance(
                node.func,
                ast.Name,
            ):

                raise SyntaxError(
                    "Q only permits named calls"
                )

            name = node.func.id

            if (
                name not in ALLOWED_CALLS
                and name not in {
                    n.name
                    for n in ast.walk(tree)
                    if isinstance(
                        n,
                        ast.FunctionDef,
                    )
                }
            ):

                raise SyntaxError(
                    f"unknown Q function: {name}"
                )


# ---------------------------------------------------------------------------
# COMPILER
# ---------------------------------------------------------------------------

def run_q(
    source: str,
    data: bytes,
    trace: Optional[
        OpticalTrace
    ] = None,
):

    machine = ReducedValveMachine(
        width=32,
        trace=trace,
    )

    runtime = QRuntime(
        machine,
        data,
    )

    variables = {}

    tree = ast.parse(
        source,
        filename="<Q>",
        mode="exec",
    )

    validate_q(tree)

    executor = StatementExecutor(
        machine,
        variables,
        runtime,
    )

    executor.visit(tree)

    return (
        variables,
        machine,
    )


# ---------------------------------------------------------------------------
# SHA-256 CHECK
# ---------------------------------------------------------------------------

def q_sha256(
    source: str,
    data: bytes,
    trace: Optional[
        OpticalTrace
    ] = None,
):

    variables, machine = run_q(
        source,
        data,
        trace,
    )

    try:

        digest = "".join(
            f"{u32(variables[name]):08x}"
            for name in (
                "h0",
                "h1",
                "h2",
                "h3",
                "h4",
                "h5",
                "h6",
                "h7",
            )
        )

    except KeyError:

        raise RuntimeError(
            "Q program did not produce "
            "h0..h7"
        )

    return digest, machine


# ---------------------------------------------------------------------------
# SELF TEST
# ---------------------------------------------------------------------------

def self_test(
    source: str,
):

    tests = [
        b"",
        b"a",
        b"abc",
        b"hello",
        b"hello world",
        b"The quick brown fox jumps over the lazy dog",
        b"The quick brown fox jumps over the lazy dog.",
        b"a" * 55,
        b"a" * 56,
        b"a" * 57,
        b"a" * 63,
        b"a" * 64,
        b"a" * 65,
        b"a" * 1000,
    ]

    for data in tests:

        got, _ = q_sha256(
            source,
            data,
        )

        expected = hashlib.sha256(
            data
        ).hexdigest()

        if got != expected:

            raise AssertionError(
                "\nSHA-256 FAILURE\n"
                f"length : {len(data)}\n"
                f"Q      : {got}\n"
                f"hashlib: {expected}"
            )

        print(
            f"PASS "
            f"{len(data):5d} bytes "
            f"{got}"
        )

    print()
    print(
        "All Q SHA-256 tests passed."
    )


