# CLI
# ---------------------------------------------------------------------------

def main():

    parser = argparse.ArgumentParser(
        description=(
            "Q optical compiler/interpreter"
        )
    )

    parser.add_argument(
        "--program",
        "-p",
        help="Q source file",
    )

    parser.add_argument(
        "--input",
        help="UTF-8 string input",
    )

    parser.add_argument(
        "--file",
        "-f",
        help="binary input file",
    )

    parser.add_argument(
        "--hex",
        help="hexadecimal input",
    )

    parser.add_argument(
        "--stdin",
        action="store_true",
        help="read binary input from stdin",
    )

    parser.add_argument(
        "--trace",
        action="store_true",
        help="display optical operations",
    )

    parser.add_argument(
        "--trace-limit",
        type=int,
        default=100,
    )

    parser.add_argument(
        "--self-test",
        action="store_true",
    )

    args = parser.parse_args()

    if not args.program:

        parser.error(
            "--program is required"
        )

    with open(
        args.program,
        "r",
        encoding="utf-8",
    ) as file:

        source = file.read()

    if args.input is not None:

        data = args.input.encode(
            "utf-8"
        )

    elif args.file:

        with open(
            args.file,
            "rb",
        ) as file:

            data = file.read()

    elif args.hex is not None:

        data = bytes.fromhex(
            args.hex
        )

    elif args.stdin:

        data = (
            sys.stdin.buffer.read()
        )

    else:

        data = b""

    if args.self_test:

        self_test(source)
        return

    trace = (
        OpticalTrace()
        if args.trace
        else OpticalTrace()
    )

    digest, machine = q_sha256(
        source,
        data,
        trace,
    )

    print(digest)

    if args.trace:

        print()
        print(
            f"optical events: "
            f"{len(machine.trace.events)}"
        )

        machine.trace.print(
            args.trace_limit
        )


if __name__ == "__main__":
    main()
