```

And the most useful verification mode is:

```text
python q_compiler.py --program sha256.q --self-test
```

That compares the **SHA-256 produced by the `.q` program** against Python's `hashlib.sha256` for several message lengths, including the 55/56/57 and 63/64/65-byte padding boundaries.

One important distinction: this is now a **Q-level SHA-256 implementation executed through the optical abstraction layer**. `hashlib` is used only by `--self-test` as an external correctness oracle; it is not used to calculate the Q digest.

#!/usr/bin/env python3
"""
Reduced-valve optical Q compiler/interpreter.

Features
--------
- Time-multiplexed binary optical operations
- 32-bit arithmetic
- AND32 / OR32 / XOR32 / NOT32
- ADD32
- SHR / SHL / ROTR
- Lists
- List indexing
- List assignment
- Functions
- Return
- If / else
- While
- For / range
- SHA-256 capable Q programs
- Optical operation tracing
- Optical statistics
- Simulator backend

Example:

    python reduced_valve_optical_stats.py \
        --program sha256.q \
        --input abc

Self-test:

    python reduced_valve_optical_stats.py \
        --program sha256.q \
        --self-test

Trace:

    python reduced_valve_optical_stats.py \
        --program sha256.q \
        --input abc \
        --trace \
        --trace-limit 100

Stats:

    python reduced_valve_optical_stats.py \
        --program sha256.q \
        --input abc \
        --stats
"""

from __future__ import annotations

import argparse
import ast
import hashlib
import sys

from dataclasses import dataclass, field
from typing import Any, Iterable, Optional


# ============================================================
# CONSTANTS
# ============================================================

MAX_LOOP_ITERATIONS = 1_000_000
MASK32 = 0xFFFFFFFF


# ============================================================
# VALIDATION
# ============================================================

def _nonnegative_int(
    name: str,
    value: Any,
) -> int:

    if isinstance(value, bool):
        raise ValueError(
            f"{name} expects an integer"
        )

    if not isinstance(value, int):
        raise ValueError(
            f"{name} expects an integer, "
            f"got {value!r}"
        )

    if value < 0:
        raise ValueError(
            f"{name} expects a nonnegative "
            f"integer, got {value!r}"
        )

    return value


def _bit(
    name: str,
    value: Any,
) -> int:

    value = _nonnegative_int(
        name,
        value,
    )

    if value not in (0, 1):
        raise ValueError(
            f"{name} expects 0 or 1, "
            f"got {value!r}"
        )

    return value


def _u32(
    value: int,
) -> int:

    return int(value) & MASK32


# ============================================================
# BIT CONVERSION
# ============================================================

def int_to_bits(
    value: int,
    width: Optional[int] = None,
) -> list[int]:

    value = _nonnegative_int(
        "value",
        value,
    )

    if width is None:
        width = max(
            1,
            value.bit_length(),
        )

    if width < 1:
        raise ValueError(
            "width must be positive"
        )

    if value >= (1 << width):
        raise ValueError(
            f"{value} does not fit "
            f"in {width} bits"
        )

    return [
        (value >> i) & 1
        for i in range(width)
    ]


def bits_to_int(
    bits: Iterable[int],
) -> int:

    result = 0

    for i, value in enumerate(bits):

        result |= (
            _bit(
                "bit",
                int(value),
            )
            << i
        )

    return result


