class SimulatedOptics:
    """
    Deterministic optical hardware simulator.

    The two-valve concept is represented by reusable bit
    operations rather than unary hole-count arithmetic.
    """

    def and_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        return (
            _bit("a", a)
            &
            _bit("b", b)
        )

    def sum_bits(
        self,
        values: Iterable[int],
    ) -> int:

        return sum(
            _bit(
                "value",
                int(v),
            )
            for v in values
        )

    def sample(
        self,
        value: int,
    ) -> int:

        return int(value)


