class OpticalBackend:

    def __init__(
        self,
        driver: Optional[Any] = None,
        valve_count: int = 2,
    ):

        self.driver = (
            driver
            or SimulatedOptics()
        )

        self.valve_count = valve_count

    def and_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        return _bit(
            "AND result",
            self.driver.and_bit(
                a,
                b,
            ),
        )

    def sum_bits(
        self,
        values: Iterable[int],
    ) -> int:

        return int(
            self.driver.sum_bits(values)
        )

    def sample(
        self,
        value: int,
    ) -> int:

        return int(
            self.driver.sample(value)
        )


