# ============================================================
# REDUCED VALVE MACHINE
# ============================================================

class ReducedValveMachine:

    def __init__(
        self,
        backend: Optional[
            OpticalBackend
        ] = None,
        width: int = 32,
        trace: Optional[
            OpticalTrace
        ] = None,
        stats: Optional[
            OpticalStats
        ] = None,
    ):

        self.backend = (
            backend
            or OpticalBackend()
        )

        self.width = width

        self.trace = (
            trace
            or OpticalTrace()
        )

        self.stats = (
            stats
            or OpticalStats()
        )

    # --------------------------------------------------------
    # RECORD
    # --------------------------------------------------------

    def _record(
        self,
        operation: str,
        inputs: tuple[Any, ...],
        result: Any,
    ) -> Any:

        self.stats.record(
            operation
        )

        return self.trace.record(
            operation,
            inputs,
            result,
        )

    # --------------------------------------------------------
    # BIT OPERATIONS
    # --------------------------------------------------------

    def and_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        result = self.backend.and_bit(
            _bit("a", a),
            _bit("b", b),
        )

        return self._record(
            "AND",
            (a, b),
            result,
        )

    def or_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        total = self.backend.sum_bits(
            [
                _bit("a", a),
                _bit("b", b),
            ]
        )

        result = int(total > 0)

        return self._record(
            "OR",
            (a, b),
            result,
        )

    def xor_bit(
        self,
        a: int,
        b: int,
    ) -> int:

        total = self.backend.sum_bits(
            [
                _bit("a", a),
                _bit("b", b),
            ]
        )

        result = total & 1

        return self._record(
            "XOR",
            (a, b),
            result,
        )

    def not_bit(
        self,
        a: int,
    ) -> int:

        result = 1 - _bit(
            "NOT",
            a,
        )

        return self._record(
            "NOT",
            (a,),
            result,
        )

    # --------------------------------------------------------
    # SERIAL BINARY
    # --------------------------------------------------------

    def _serial_binary(
        self,
        a: int,
        b: int,
        operation: str,
        width: Optional[int] = None,
    ) -> int:

        width = (
            width
            or self.width
        )

        a = _u32(a)
        b = _u32(b)

        abits = int_to_bits(
            a,
            width,
        )

        bbits = int_to_bits(
            b,
            width,
        )

        output = []

        for slot, (
            ai,
            bi,
        ) in enumerate(
            zip(
                abits,
                bbits,
            )
        ):

            if operation == "AND":

                value = (
                    self.backend.and_bit(
                        ai,
                        bi,
                    )
                )

            elif operation == "OR":

                value = int(
                    self.backend.sum_bits(
                        [ai, bi]
                    ) > 0
                )

            elif operation == "XOR":

                value = (
                    self.backend.sum_bits(
                        [ai, bi]
                    )
                    & 1
                )

            else:

                raise ValueError(
                    f"unknown operation "
                    f"{operation}"
                )

            output.append(
                value
            )

            self._record(
                f"{operation}[t={slot}]",
                (ai, bi),
                value,
            )

        return bits_to_int(
            output
        )

    # --------------------------------------------------------
    # 32 BIT LOGIC
    # --------------------------------------------------------

    def and32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return MASK32

        result = _u32(
            values[0]
        )

        for value in values[1:]:

            result = (
                self._serial_binary(
                    result,
                    _u32(value),
                    "AND",
                    32,
                )
                & MASK32
            )

        return self._record(
            "AND32",
            tuple(values),
            result,
        )

    def or32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return 0

        result = _u32(
            values[0]
        )

        for value in values[1:]:

            result = (
                self._serial_binary(
                    result,
                    _u32(value),
                    "OR",
                    32,
                )
                & MASK32
            )

        return self._record(
            "OR32",
            tuple(values),
            result,
        )

    def xor32(
        self,
        *values: int,
    ) -> int:

        if not values:
            return 0

        result = _u32(
            values[0]
        )

        for value in values[1:]:

            result = (
                self._serial_binary(
                    result,
                    _u32(value),
                    "XOR",
                    32,
                )
                & MASK32
            )

        return self._record(
            "XOR32",
            tuple(values),
            result,
        )

    def not32(
        self,
        value: int,
    ) -> int:

        result = (
            ~_u32(value)
        ) & MASK32

        return self._record(
            "NOT32",
            (value,),
            result,
        )

    # --------------------------------------------------------
    # ADDITION
    # --------------------------------------------------------

    def _add_raw(
        self,
        a: int,
        b: int,
    ) -> int:

        carry = 0
        result = 0

        for slot in range(32):

            ai = (
                a >> slot
            ) & 1

            bi = (
                b >> slot
            ) & 1

            total = (
                self.backend.sum_bits(
                    [
                        ai,
                        bi,
                        carry,
                    ]
                )
            )

            output_bit = (
                total & 1
            )

            carry = int(
                total >= 2
            )

            result |= (
                output_bit
                << slot
            )

            self._record(
                f"ADD32[t={slot}]",
                (
                    ai,
                    bi,
                    carry,
                ),
                output_bit,
            )

        return result & MASK32

    def add32(
        self,
        *values: int,
    ) -> int:

        result = 0

        for value in values:

            result = self._add_raw(
                result,
                _u32(value),
            )

        result &= MASK32

        return self._record(
            "ADD32",
            tuple(values),
            result,
        )

    # --------------------------------------------------------
    # SUBTRACT
    # --------------------------------------------------------

    def subtract(
        self,
        a: int,
        b: int,
    ) -> int:

        result = (
            _u32(a)
            -
            _u32(b)
        ) & MASK32

        return self._record(
            "SUB32",
            (a, b),
            result,
        )

    # --------------------------------------------------------
    # SHIFTS
    # --------------------------------------------------------

    def shr(
        self,
        value: int,
        amount: int,
    ) -> int:

        value = _u32(value)
        amount = int(amount)

        if amount >= 32:
            result = 0
        else:
            result = (
                value >> amount
            )

        return self._record(
            "SHR",
            (value, amount),
            result,
        )

    def shl(
        self,
        value: int,
        amount: int,
    ) -> int:

        result = (
            _u32(value)
            << int(amount)
        ) & MASK32

        return self._record(
            "SHL",
            (value, amount),
            result,
        )

    def rotr(
        self,
        value: int,
        amount: int,
    ) -> int:

        value = _u32(value)

        amount %= 32

        if amount == 0:

            result = value

        else:

            result = (
                (value >> amount)
                |
                (
                    value
                    << (32 - amount)
                )
            ) & MASK32

        return self._record(
            "ROTR",
            (value, amount),
            result,
        )

    # --------------------------------------------------------
    # MULTIPLY
    # --------------------------------------------------------

    def multiply(
        self,
        a: int,
        b: int,
    ) -> int:

        result = 0
        row = _u32(a)

        b = _u32(b)

        shift = 0

        while (
            b >> shift
        ):

            if (
                (b >> shift) & 1
            ):

                result = self.add32(
                    result,
                    row,
                )

            row = (
                row << 1
            ) & MASK32

            shift += 1

        return self._record(
            "MUL32",
            (a, b),
            result,
        )

    # --------------------------------------------------------
    # COMPARISON
    # --------------------------------------------------------

    def compare(
        self,
        a: int,
        b: int,
    ) -> int:

        if a == b:
            result = 0

        elif a > b:
            result = 1

        else:
            result = -1

        return self._record(
            "CMP",
            (a, b),
            result,
        )

    def eq(self, a, b):
        return int(
            self.compare(a, b) == 0
        )

    def ne(self, a, b):
        return int(
            self.compare(a, b) != 0
        )

    def lt(self, a, b):
        return int(
            self.compare(a, b) < 0
        )

    def le(self, a, b):
        return int(
            self.compare(a, b) <= 0
        )

    def gt(self, a, b):
        return int(
            self.compare(a, b) > 0
        )

    def ge(self, a, b):
        return int(
            self.compare(a, b) >= 0
        )


# ============================================================
# Q RUNTIME
# ============================================================

class QRuntime:

    def __init__(
        self,
        machine: ReducedValveMachine,
        data: bytes,
    ):

        self.machine = machine
        self.data = bytes(data)

    def byte(
        self,
        index: int,
    ) -> int:

        index = int(index)

        if (
            index < 0
            or index >= len(self.data)
        ):

            return 0

        return self.data[index]

    def length(self) -> int:

        return len(self.data)

    def padded(
        self,
    ) -> bytes:

        message = bytearray(
            self.data
        )

        bit_length = (
            len(message)
            * 8
        )

        message.append(
            0x80
        )

        while (
            len(message) % 64
            != 56
        ):

            message.append(
                0
            )

        message.extend(
            bit_length.to_bytes(
                8,
                "big",
            )
        )

        return bytes(message)

    def word(
        self,
        index: int,
    ) -> int:

        data = self.padded()

        offset = (
            int(index)
            * 4
        )

        if (
            offset + 4
            > len(data)
        ):

            return 0

        return int.from_bytes(
            data[
                offset:
                offset + 4
            ],
            "big",
        )

    def word_count(
        self,
    ) -> int:

        return (
            len(self.padded())
            // 4
        )


