# MAIN
# ============================================================

def main():

    parser = argparse.ArgumentParser(
        description=(
            "Reduced-valve optical Q compiler"
        )
    )

    parser.add_argument(
        "--program",
        "-p",
        required=True,
        help="Q source file",
    )

    parser.add_argument(
        "--input",
        help="UTF-8 input string",
    )

    parser.add_argument(
        "--file",
        "-f",
        help="binary input file",
    )

