from __future__ import annotations

"""Optical backend -> Qiskit qubit-state preparation demo.

The camera/optical bench supplies a calibrated intensity value per channel.
Each channel maps to a Qiskit RY preparation angle. Qiskit then models the
prepared qubits, applies optional entanglement, and samples readout.

Synthetic:
    python optical_backend_qubits.py --demo --synthetic --shots 8192
Live camera:
    python optical_backend_qubits.py --demo --camera 0 --roi 100 80 900 600
"""

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Optional, Sequence
import argparse
import time

import cv2
import numpy as np

try:
    import qiskit  # noqa: F401
    from qiskit import QuantumCircuit
    from qiskit.primitives import StatevectorSampler
    QISKIT_AVAILABLE = True
except ImportError:
    QISKIT_AVAILABLE = False


@dataclass
class CameraConfig:
    camera_index: int = 0
    width: int = 1280
    height: int = 720
    exposure: Optional[float] = None
    gain: Optional[float] = None
    warmup_frames: int = 12


class OpenCVCamera:
    def __init__(self, config: CameraConfig):
        self.cap = cv2.VideoCapture(config.camera_index)
        if not self.cap.isOpened():
            raise RuntimeError(f"Cannot open camera {config.camera_index}; use --synthetic or set --camera.")
        self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, config.width)
        self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, config.height)
        if config.exposure is not None:
            self.cap.set(cv2.CAP_PROP_EXPOSURE, config.exposure)
        if config.gain is not None:
            self.cap.set(cv2.CAP_PROP_GAIN, config.gain)
        for _ in range(max(0, config.warmup_frames)):
            self.read()

    def read(self) -> np.ndarray:
        ok, frame = self.cap.read()
        if not ok or frame is None:
            raise RuntimeError("Camera frame acquisition failed")
        return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)

    def close(self) -> None:
        if getattr(self, "cap", None) is not None:
            self.cap.release()
            self.cap = None


class SyntheticCamera:
    """Test camera that produces a grid image proportional to optical channel values."""
    def __init__(self, frame_shape=(720, 1280), noise_std=1.5, seed=2026):
        self.frame_shape = tuple(frame_shape)
        self.noise_std = float(noise_std)
        self.rng = np.random.default_rng(seed)
        self.matrix: Optional[np.ndarray] = None

    def set_matrix(self, matrix: np.ndarray) -> None:
        self.matrix = np.asarray(matrix, dtype=np.float32)

    def read(self) -> np.ndarray:
        if self.matrix is None:
            raise RuntimeError("SyntheticCamera needs set_matrix() before read()")
        rows, cols = self.matrix.shape
        h, w = self.frame_shape
        output = np.full((h, w), 12.0, dtype=np.float32)
        maximum = max(float(self.matrix.max()), 1.0)
        for r in range(rows):
            y0, y1 = round(r*h/rows), round((r+1)*h/rows)
            for c in range(cols):
                x0, x1 = round(c*w/cols), round((c+1)*w/cols)
                output[y0:y1, x0:x1] = 20.0 + 220.0 * self.matrix[r, c] / maximum
        output += self.rng.normal(0.0, self.noise_std, output.shape)
        return np.clip(output, 0, 255).astype(np.uint8)

    def close(self) -> None:
        pass


class OpticalBench:
    """Camera acquisition, correction, grid decoding, and intensity calibration."""
    def __init__(
        self,
        camera: Any,
        output_shape: Sequence[int],
        roi: Optional[Sequence[int]] = None,
        background: Optional[np.ndarray] = None,
        flat_field: Optional[np.ndarray] = None,
        calibration: Optional[tuple[float, float]] = None,
    ):
        self.camera = camera
        self.output_shape = tuple(map(int, output_shape))
        if len(self.output_shape) != 2 or min(self.output_shape) <= 0:
            raise ValueError("output_shape must be (rows, columns), all positive")
        self.roi = tuple(map(int, roi)) if roi is not None else None
        self.background = background
        self.flat_field = flat_field
        self.calibration = calibration

    @staticmethod
    def load_image(path: str | Path) -> np.ndarray:
        image = cv2.imread(str(path), cv2.IMREAD_GRAYSCALE)
        if image is None:
            raise FileNotFoundError(path)
        return image.astype(np.float32)

    @staticmethod
    def _match(image: np.ndarray, shape: tuple[int, int]) -> np.ndarray:
        image = np.asarray(image, dtype=np.float32)
        return image if image.shape == shape else cv2.resize(image, (shape[1], shape[0]))

    def capture(self) -> np.ndarray:
        frame = self.camera.read().astype(np.float32)
        if self.roi is not None:
            x, y, w, h = self.roi
            if x < 0 or y < 0 or w <= 0 or h <= 0:
                raise ValueError("ROI must be X Y WIDTH HEIGHT")
            frame = frame[y:y+h, x:x+w]
            if frame.size == 0:
                raise ValueError("ROI is outside the camera frame")
        if self.background is not None:
            frame -= self._match(self.background, frame.shape)
        if self.flat_field is not None:
            frame /= np.maximum(self._match(self.flat_field, frame.shape), 1.0)
        return np.maximum(frame, 0.0)

    def decode_grid(self, frame: np.ndarray) -> np.ndarray:
        rows, cols = self.output_shape
        height, width = frame.shape
        decoded = np.zeros((rows, cols), dtype=np.float32)
        for r in range(rows):
            y0, y1 = round(r*height/rows), round((r+1)*height/rows)
            for c in range(cols):
                x0, x1 = round(c*width/cols), round((c+1)*width/cols)
                decoded[r, c] = float(frame[y0:y1, x0:x1].mean())
        return decoded

    def fit_linear_calibration(self, raw: np.ndarray, expected: np.ndarray) -> tuple[float, float]:
        alpha, beta = np.polyfit(np.asarray(raw).ravel(), np.asarray(expected).ravel(), 1)
        self.calibration = (float(alpha), float(beta))
        return self.calibration

    def calibrated_values(self, raw: np.ndarray, max_value: float) -> np.ndarray:
        if self.calibration is not None:
            alpha, beta = self.calibration
            values = alpha * raw + beta
        else:
            lo, hi = float(raw.min()), float(raw.max())
            values = np.zeros_like(raw) if hi <= lo else (raw-lo)*max_value/(hi-lo)
        return np.clip(values, 0.0, max_value).astype(np.float32)

    def capture_optical_matrix(self, max_value: float) -> dict[str, np.ndarray]:
        frame = self.capture()
        raw = self.decode_grid(frame)
        values = self.calibrated_values(raw, max_value=max_value)
        return {"camera_frame": frame, "optical_raw": raw, "optical_values": values}


class OpticalJob:
    def __init__(self, backend: Any, job_id: str, result: dict):
        self._backend, self._job_id, self._result = backend, job_id, result
    def backend(self): return self._backend
    def job_id(self): return self._job_id
    def status(self): return "DONE"
    def done(self): return True
    def submit(self): return None
    def result(self, timeout: Optional[float] = None): return self._result


class OpticalStateBackend:
    """Optical state-preparation backend. It provides camera-decoded qubit channels."""
    def __init__(self, bench: OpticalBench, name="optical_state_backend"):
        self.bench, self.name = bench, name

    def run(self, max_value: float = 1.0) -> OpticalJob:
        data = self.bench.capture_optical_matrix(max_value=max_value)
        job_id = f"optical-{time.time_ns()}"
        return OpticalJob(self, job_id, {"backend_name": self.name, "job_id": job_id, "success": True, "data": data})


def optical_matrix_to_qubit_angles(optical_matrix: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """One optical output row supplies one qubit's state-preparation angle."""
    matrix = np.asarray(optical_matrix, dtype=np.float64)
    if matrix.ndim != 2 or matrix.size == 0:
        raise ValueError("optical_matrix must be a non-empty 2-D array")
    row_intensity = matrix.mean(axis=1)
    lo, hi = float(row_intensity.min()), float(row_intensity.max())
    normalized = np.full_like(row_intensity, 0.5) if np.isclose(lo, hi) else (row_intensity-lo)/(hi-lo)
    angles = np.pi * normalized
    return row_intensity, normalized, angles


def build_optical_backend_circuit(optical_matrix: np.ndarray, entangle: bool = True):
    """Optical intensity channels become Qiskit qubit state-preparation gates."""
    if not QISKIT_AVAILABLE:
        raise RuntimeError("Install Qiskit with: python -m pip install -U qiskit")
    row_intensity, normalized, angles = optical_matrix_to_qubit_angles(optical_matrix)
    qubits = len(angles)
    circuit = QuantumCircuit(qubits, qubits, name="optical_state_backend")

    # The calibrated optical backend supplies these RY-prepared qubit states.
    for q, theta in enumerate(angles):
        circuit.ry(float(theta), q)

    circuit.barrier(label="optical_backend_state")

    # Downstream quantum processing after optical preparation.
    if entangle and qubits > 1:
        for q in range(qubits - 1):
            circuit.cx(q, q + 1)
        for q in range(qubits - 1, 0, -1):
            circuit.cx(q, q - 1)

    circuit.barrier(label="readout")
    circuit.measure(range(qubits), range(qubits))
    return circuit, {
        "input_shape": tuple(np.asarray(optical_matrix).shape),
        "num_qubits": qubits,
        "optical_row_intensity": row_intensity,
        "normalized_optical_channel": normalized,
        "state_preparation_angles_radians": angles,
        "state_preparation_angles_degrees": np.degrees(angles),
    }


def run_via_qiskit(circuit, shots: int = 8192, seed: int = 1234) -> dict:
    """Run the prepared state through Qiskit's current V2 StatevectorSampler."""
    if not QISKIT_AVAILABLE:
        raise RuntimeError("Install Qiskit with: python -m pip install -U qiskit")
    sampler = StatevectorSampler(default_shots=shots, seed=seed)
    pub = sampler.run([circuit], shots=shots).result()[0]
    names = list(pub.data)
    if not names:
        raise RuntimeError("No measured classical register returned by Qiskit")
    counts = dict(pub.data[names[0]].get_counts()) if len(names) == 1 else dict(pub.join_data().get_counts())
    return {"engine": "qiskit.primitives.StatevectorSampler", "shots": shots, "classical_registers": names, "counts": counts}


def decode_counts(counts: dict[str, int], top_k: int = 16) -> list[dict]:
    total = max(sum(counts.values()), 1)
    return [
        {"bitstring": bits.replace(" ", ""), "count": count, "probability": count/total}
        for bits, count in sorted(counts.items(), key=lambda item: item[1], reverse=True)[:top_k]
    ]


