            frame /= np.maximum(self._match(self.flat_field, frame.shape), 1.0)
        return np.maximum(frame, 0.0)

    def decode_grid(self, frame: np.ndarray) -> np.ndarray:
        rows, cols = self.output_shape
        height, width = frame.shape
        decoded = np.zeros((rows, cols), dtype=np.float32)
        for r in range(rows):
            y0, y1 = round(r*height/rows), round((r+1)*height/rows)
            for c in range(cols):
                x0, x1 = round(c*width/cols), round((c+1)*width/cols)
                decoded[r, c] = float(frame[y0:y1, x0:x1].mean())
        return decoded

    def fit_linear_calibration(self, raw: np.ndarray, expected: np.ndarray) -> tuple[float, float]:
        alpha, beta = np.polyfit(np.asarray(raw).ravel(), np.asarray(expected).ravel(), 1)
        self.calibration = (float(alpha), float(beta))
        return self.calibration

    def calibrated_values(self, raw: np.ndarray, max_value: float) -> np.ndarray:
        if self.calibration is not None:
